def grid_of(txt):
    i = txt.find('{')
    # find last JSON object
    j = txt.rfind('}')
    # try progressively
    for start in [i]:
        try:
            obj = json.loads(txt[start:j+1])
            if obj.get("action")=="submit":
                return obj["grid"]
        except Exception as e:
            pass
    # fallback: regex for "grid": [[...]]
    m = re.search(r'"grid"\s*:\s*(\[\[.*?\]\])', txt, re.S)
    return json.loads(m.group(1)) if m else None

