def ringseq(G, r0=1, c0=1, n=25):
    sq = [row[c0:c0+n] for row in G[r0:r0+n]]
    seq = []
    for d in range(n//2 + 1):
        # ring color(s) at depth d
        ring = set()
        for x in range(d, n-d):
            ring.add(sq[d][x]); ring.add(sq[n-1-d][x])
            ring.add(sq[x][d]); ring.add(sq[x][n-1-d])
        seq.append(sorted(ring))
    return seq

